from pathlib import Path
import json, hashlib
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[3]
data=json.loads((OUT/'specialty-inventory.json').read_text())
affected={'strategy','simulation','sports'}
def closure(ids):
 return [(i,p) for i in ids for p in data['graph']['parents'][i] if p not in ids]
lines=['# Handoff 016 — specialty roster review', '', '2026-10-18. **DESIGN review COMPLETE; recommendation OPEN, not implemented.** Handoff 015 implements the four acquisition edges. This review uses its native inventory in [specialty-inventory.json](specialty-inventory.json) and unchanged ledger/roster sources pinned by `store-render-v2/source.json`. The live verifier checks all eight existing grants and their retained supply. No balance study or specialty mutation was performed.', '', '## Recommendation', '', 'For a separately approved future-start roster v2, replace `maps` with `levels` in Strategy, Simulation and Sports only. Keep the other five exact rosters below. This preserves count, total Scope, common six and every named signature, removes all purchase-parent exceptions, and makes Maps a visible optional child. It exchanges printed Technology 2 for Design 2 in each affected grant, retaining Graphics 3 and Scope 2. That Core tradeoff and loss of immediate Maps are explicit design costs, not evidence of balance.', '', '| Specialty | Before IDs | Proposed v2 IDs | Count before → after | Scope before → after | Parent closure before → after |', '|---|---|---|---|---|---|']
proposals=[]
for row in data['rows']:
 old=row['ids'];new=[('levels' if i=='maps' and row['id'] in affected else i) for i in old]
 assert len(new)==len(set(new)) and not closure(new)
 scope=sum(int(data['definitions'][i]['scope']) for i in new)
 proposals.append({'specialty':row['id'],'before':old,'proposal':new,'count':len(new),'scope':scope})
 lines.append('| %s | %s | %s | %d → %d | %d → %d | %s → closed |'%(row['name'],', '.join('`'+i+'`' for i in old),', '.join('`'+i+'`' for i in new),row['count'],len(new),row['scope'],scope,'Maps lacks Levels' if closure(old) else 'closed'))
lines+=['', '## Alternatives for each of the three exceptions', '', '| Approach | Strategy count/Scope | Simulation count/Scope | Sports count/Scope | Consequence |', '|---|---|---|---|---|', '| Add Levels and keep Maps | 18 / 28 | 17 / 26 | 16 / 26 | Parent-closed; adds a free $450 Feature, Graphics 3 + Design 2, one finite card and Scope 2. Keeps Technology 2 from Maps. A real starting-pool/economy expansion. |', '| **Replace Maps with Levels (recommended)** | **17 / 26** | **16 / 24** | **15 / 24** | Parent-closed with equal count/Scope/acquisition list price; Technology −2, Design +2. Maps becomes optional. |', '| Explicit Maps grant exception | 17 / 26 | 16 / 24 | 15 / 24 | Current Stage 1; no roster change. Maps works without Levels, but buying Exploration still requires Levels. Keep the exception visibly labeled. |', '', '## First-game access and optional buying', '', '- Recommended v2: Maps costs its unchanged $450; its owned Levels parent permits immediate zero-cycle optional buying. Before, Maps was free and Levels cost $450. Buying both yields the same final ownership set and $450 total optional spend under either roster.', '- Exploration costs $300 with the proposed Levels grant. Under current Strategy/Simulation/Sports, acquiring unowned Exploration requires Levels ($450) first, then Exploration ($300): $750 total. The shared ancestor is counted once.', '- No new cost for an already-owned child in Stage 1. All other specialty purchase routes retain the implemented four gates. Simple Story → Dialogue/Character Backstories and all downstream AND gates are unchanged by this proposal.', '- No new draw, play, Scope completion or Review guarantee follows from ownership. A cheaper route to Exploration and the two-Core exchange could change first-game outcomes; that balance question is OPEN. All recommended initial Scope totals remain below 30.', '', '## Migration and creation preview', '', '- Future starts only: introduce explicit fixed roster version 2 at creation. Persist that founding provenance; absent version means historical v1. Store actual granted IDs as provenance if version validation needs them, separate from the current owned set which may include later acquisitions.', '- Existing Studios, queued purchases, frozen project supply, Contract pools and released history remain exactly as saved. Never recompute ownership from the new roster or grant/remove/refund Maps or Levels during Continue. No switch of Studio specialty or project Genre.', '- Preview wording for affected v2 specialties: “Starting Features: [exact list]. Levels is granted. Maps can be purchased for $450 before your first project (0 cycles); later purchases use Research. [count] Features · [Scope] printed Scope.” Preserve the complete list and the current common/favored/signature explanation only if it accurately reflects the explicit replacement.', '- Old Studio map wording remains “Owned · retained grant / prior ownership” when a purchased parent is absent. Do not imply that the purchase gate was fulfilled.', '', '## Approval boundary', '', 'The exact three substitutions, roster version 2 and preview wording above are recommendations requiring a separate ruling. No specialty gameplay, price, play fee, Review target, Core printed value, Contract supply or existing-save ownership changed in this review. After approval, create a separate implementation handoff with creation, legacy/current Continue, supply and all-eight-roster acceptance. Human Store comprehension and broader balance remain deferred.']
(OUT/'SPECIALTY-REVIEW.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
(OUT/'specialty-proposal.json').write_text(json.dumps(proposals,indent=2)+'\n')
print('Eight exact roster comparisons; all proposed rosters parent-closed; no runtime edit')
